fn fibonacci(n: usize) -> Vec<i32> {
    // Problem statement assumes n >= 2
    let mut ret: Vec<i32> = Vec::with_capacity(n);

    ret.push(0);
    ret.push(1);

    while ret.len() < n {
        let len = ret.len();
        let next = ret[len - 1] + ret[len - 2];
        ret.push(next);
    }

    ret
}